function createPanelShader() {
  const pos = TSL.varyingProperty('vec3', 'vPosition');

  // Normalize to panel bounds [-1.6, 1.6] x [-1.1, 1.1]
  const normalizedPos = new THREE.Vector2(pos.x.div(1.6), pos.y.div(1.1));

  // Radial gradient: center #14141a → edges #0b0b10
  const distFromCenter = TSL.length(normalizedPos);
  const colorCenter = new THREE.Color(0x14141a);
  const colorEdge = new THREE.Color(0x0b0b10);
  const radialGradient = TSL.mix(
    colorCenter,
    colorEdge,
    TSL.clamp(distFromCenter, 0, 1)
  );

  // Grid pattern (0.25 unit pitch = 4 lines per unit)
  const gridUV = TSL.fract(normalizedPos.mul(4));
  const gridThreshold = 0.96;
  const gridLineX = TSL.step(gridThreshold, gridUV.x);
  const gridLineY = TSL.step(gridThreshold, gridUV.y);
  const gridPattern = gridLineX.add(gridLineY);

  const gridColor = new THREE.Color(0xe8ecf2);
  const withGrid = TSL.mix(radialGradient, gridColor, gridPattern.mul(0.06));

  return withGrid;
}

function createGhostPreview() {
  const group = new THREE.Group();

  // Card outline: 1.1w x 1.4h
  const cardGeometry = new THREE.BufferGeometry();
