  ]);
  cardGeometry.setAttribute('position', new THREE.BufferAttribute(cardVertices, 3));
  const cardMaterial = new THREE.LineBasicMaterial({
    color: 0xe8ecf2,
    linewidth: 1,
    transparent: true,
    opacity: 0.3,
  });
  const cardLines = new THREE.LineSegments(cardGeometry, cardMaterial);
  group.add(cardLines);

  // Ghost dial: circle 0.55 diameter (radius 0.275)
  const dialGeometry = new THREE.BufferGeometry();
  const dialVertices = [];
  const segments = 32;
  for (let i = 0; i <= segments; i++) {
    const angle = (i / segments) * Math.PI * 2;
    dialVertices.push(
      Math.cos(angle) * 0.275,
      Math.sin(angle) * 0.275,
      0
    );
  }
  dialGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(dialVertices), 3));
  const dialMaterial = new THREE.LineBasicMaterial({
    color: 0xe8ecf2,
    linewidth: 1,
    transparent: true,
    opacity: 0.22,
  });
  const dialLines = new THREE.Line(dialGeometry, dialMaterial);
  dialLines.position.y = 0.2;
  group.add(dialLines);

  // Two ghost text bars: 0.7w x 0.06h each
