    const barGeometry = new THREE.BufferGeometry();
    const barVertices = new Float32Array([
      -0.35, 0.03, 0,
      0.35, 0.03, 0,
      0.35, -0.03, 0,
      -0.35, -0.03, 0,
    ]);
    const barIndices = new Uint16Array([0, 1, 1, 2, 2, 3, 3, 0]);
    barGeometry.setAttribute('position', new THREE.BufferAttribute(barVertices, 3));
    barGeometry.setIndex(new THREE.BufferAttribute(barIndices, 1));

    const barMaterial = new THREE.LineBasicMaterial({
      color: 0xe8ecf2,
      linewidth: 1,
