function createButtonGradient() {
  const uv = TSL.varyingProperty('vec2', 'vUv');

  // Vertical gradient: top (#ff4450) → bottom (#c1121f)
  const gradient = TSL.mix(
    new THREE.Color(0xff4450),
    new THREE.Color(0xc1121f),
    uv.y
  );

  return gradient;
}
